def make_case(assessment,caseid,parts,changes,score_changes,judgments,kind):
 response=copy.deepcopy(parts)
 for key,val in changes.items(): response[key]=val
 allids=[x['id'] for x in assessment['examData']['scoring']['steps']]
 scores={k:2 for k in allids};scores.update(score_changes)
 grades=[]
 for k in allids:
  grades.append({'criterionId':k,'points':scores[k],'maxPoints':2,'reason':judgments.get(k,'The expanded answer explicitly supplies every component of this criterion, read against both-language task/solution and the runtime description.')})
 total=sum(scores.values());threshold=assessment['examData']['scoring']['passingPoints']
 return {'caseId':caseid,'assessmentId':assessment['id'],'kind':kind,'answerText':'\n\n'.join(response.values()),'criterionGrades':grades,'score':total,'threshold':threshold,'decision':'PASS_HYPOTHETICAL_DESK_CASE_ONLY' if total>=threshold else 'FAIL_MISSING_REQUIRED_PERFORMANCE','graderBoundary':'Independent semantic desk grading. Expanded answers are invented fixtures, not actual learner responses or own experiments. 2 means every named component, 1 meaningful but incomplete/incorrect part, 0 absent or fundamentally contradictory. No learner result is written.'}
