# Hypothetical individual raw records. Different presentation orders and response positions in A and B.
def series(name):
 order=[('2.40',[False,True,False,True,False]),('1.20',[True]*5),('1.80',[True,False,True,True,True])]
 if name=='B': order=[('1.80',[True,True,False,True,True]),('2.40',[False,False,True,False,True]),('1.20',[True]*5)]
 rows=[];control_count=0
 for gi,(distance,answers) in enumerate(order):
  for i,ans in enumerate(answers):
   rows.append({'distanceM':distance,'card':'pair','answer':'two lines with bright gap' if ans else 'no clear bright gap'})
   if (gi,i) in [(0,0),(0,3),(1,2),(2,1),(2,4)]:
    control_count+=1
    false=(name=='B' and control_count==3)
    rows.append({'distanceM':distance,'card':'single broad bar','answer':'two lines with bright gap' if false else 'one broad bar, no bright gap'})
 repeat=[True,True,False,True,True] if name=='A' else [True,False,True,True,True]
 for i,ans in enumerate(repeat):
  rows.append({'distanceM':'1.80','card':'pair','freshNearRepeat':True,'answer':'two lines with bright gap' if ans else 'no clear bright gap'})
  if i in [1,4]:rows.append({'distanceM':'1.80','card':'single broad bar','freshNearRepeat':True,'answer':'one broad bar, no bright gap'})
 return rows
